const main=document.querySelector('main');
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,access=null,records=[],learning={},adminRecords=[],routeVersion=0;
const can=p=>user?.role==='admin'||!!access?.[p]?.active;
const dayDate=s=>new Date(typeof s==='number'?s*1000:s).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});
const inputDate=s=>new Date((typeof s==='number'?s*1000:Date.parse(s))-3*3600000).toISOString().slice(0,10);
const productName={course:'Curso Arrivo In Itália',planner:'Meu Planner',fornitore:'Fornitore'};
const order=(a,b)=>(a.order||0)-(b.order||0)||a.title.localeCompare(b.title,'pt-BR');
const byKind=k=>records.filter(r=>r.kind===k).sort(order);
const statusName={published:'Publicado',draft:'Rascunho',archived:'Arquivado',active:'Ativo',suspended:'Suspenso',open:'Aberta',answered:'Respondida'};
const badge=s=>`<span class="status ${h(s)}">${h(statusName[s]||s)}</span>`;
const date=s=>new Date(s).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
const goto=path=>{location.hash=path;};
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',4500);}
async function api(path,method='GET',data){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Arrivo-Request':'1'},body:data===undefined?undefined:JSON.stringify(data)});let b;try{b=await res.json();}catch{throw new Error('Não foi possível conectar. Tente novamente.');}if(!res.ok){const e=new Error(b.error||'Não foi possível concluir.');e.status=res.status;e.code=b.code;throw e;}return b;}
function attachForm(id,callback){const form=document.getElementById(id);form.onsubmit=async e=>{e.preventDefault();const error=form.querySelector('.form-error');error.textContent='';const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await callback(Object.fromEntries(new FormData(form)),form);}catch(err){error.textContent=err.message;}finally{if(submit.isConnected)submit.disabled=false;}};}
const field=(label,name,value='',type='text',required=false)=>`<label>${h(label)}<input name="${h(name)}" type="${type}" value="${h(value)}" ${required?'required':''} ${type==='password'?'minlength="12" maxlength="72" autocomplete="new-password"':''}></label>`;
const area=(label,name,value='')=>`<label>${h(label)}<textarea name="${h(name)}">${h(value)}</textarea></label>`;
const errorBox='<p class="form-error" role="alert"></p>';
const select=(label,name,options,value)=>`<label>${h(label)}<select name="${h(name)}">${options.map(([v,t])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(t)}</option>`).join('')}</select></label>`;
const learnerNav=document.querySelector('header nav').innerHTML;
function frame(){
 const header=document.querySelector('header');
 const nav=header.querySelector('nav');
 const adminView=user?.role==='admin'&&location.hash.startsWith('#admin');
 header.classList.toggle('admin-view',!!adminView);
 nav.setAttribute('aria-label',adminView?'Navegação da administração':'Navegação principal');
 nav.innerHTML=adminView?menu.map(([id,label])=>`<a href="#admin${id?'/'+id:''}" data-admin-section="${h(id)}">${h(label)}</a>`).join('')+'<a href="#inicio">← Área do aluno</a>':learnerNav;
 header.querySelector('.preview-label')?.remove();header.querySelector('.avatar')?.remove();
 let account=header.querySelector('.account-nav');
 if(!account){account=document.createElement('div');account.className='account-nav';header.append(account);}
 account.innerHTML=user?`${user.role==='admin'&&!adminView?'<a href="#admin">Administração</a>':''}<a class="avatar" href="#perfil">${h(user.name.split(' ')[0])}</a><button id="logout">Sair</button>`:'';
 document.querySelector('#logout')?.addEventListener('click',async()=>{try{await api('/auth/logout','POST',{});user=null;access=null;records=[];learning={};goto('entrar');render();}catch(e){toast(e.message);}});
 document.querySelector('.journeybar').classList.toggle('hidden',user?.role!=='student'||!can('course'));
 nav.classList.toggle('hidden',!user);
 nav.querySelectorAll('[data-nav="planner"],[data-nav="fornitore"]').forEach(a=>a.classList.toggle('locked',!!user&&!can(a.dataset.nav)));
 document.querySelector('footer small').textContent='Arrivo In Itália · Área de aprendizado';
 if(user&&can('course'))updateBar();
}

function updateBar(){
 const bar=document.querySelector('.journeybar');
 bar.classList.toggle('hidden',user?.role!=='student');
 if(user?.role!=='student')return;
 const tracks=byKind('track');
 const active=tracks.find(t=>learning['active:track']===t.id)||tracks[0];
 const p=progress(active?active.groups.flatMap(g=>g[1]):[]);
 bar.querySelector('.learner small').textContent='Sua evolução na trilha';
 bar.querySelector('.learner strong').textContent=p.total&&p.percent===100?'Trilha concluída':p.done?'Em andamento':'Vamos começar';
 document.querySelector('#track-progress-label').textContent=p.total?p.done+' de '+p.total+' aulas concluídas':active?'Aulas em produção':'Nenhuma trilha disponível';
 document.querySelector('#xp-count').textContent=p.percent+'%';
 const meter=document.querySelector('#xp');meter.value=p.percent;meter.setAttribute('aria-label','Progresso em '+(active?.title||'trilha'));
 const menu=document.querySelector('#track-select');
 menu.innerHTML=tracks.length?tracks.map(t=>'<option value="'+h(t.id)+'">'+h(t.title)+' · '+progress(t.groups.flatMap(g=>g[1])).percent+'%</option>').join(''):'<option value="">Nenhuma trilha disponível</option>';
 menu.value=active?.id||'';menu.disabled=!tracks.length;
 menu.onchange=async()=>{const id=menu.value;menu.disabled=true;try{await saveLearner('active:track',id);goto('trilha/'+id);}catch(e){updateBar();toast(e.message);}};
}
let navigationRegistered=false;
async function loadCatalog(){const [c,l]=await Promise.all([api('/catalog'),api('/learner')]);records=c.records;learning=l.data;if(!navigationRegistered&&document.modelContext?.registerTool){navigationRegistered=true;try{await document.modelContext.registerTool({name:'open_learning_path',title:'Abrir trilha de aprendizado',description:'Abre uma trilha publicada disponível na conta atual, sem alterar o progresso.',inputSchema:{type:'object',properties:{path:{type:'string'}},required:['path'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!user||!input||!records.some(t=>t.kind==='track'&&t.id===input.path))throw new Error('Trilha indisponível');goto('trilha/'+input.path);await render();return{path:input.path};}});}catch{navigationRegistered=false;}}}
async function saveLearner(key,value){await api('/learner','PUT',{key,value});learning[key]=value;updateBar();}
function progress(ids){const ls=byKind('lesson').filter(l=>ids.includes(l.moduleId));return{total:ls.length,done:ls.filter(l=>learning['complete:'+l.id]===true).length,percent:ls.length?Math.round(ls.filter(l=>learning['complete:'+l.id]===true).length/ls.length*100):0};}
function poster(m){const ls=byKind('lesson').filter(l=>l.moduleId===m.id);return `<a href="#modulo/${h(m.id)}" class="poster ${m.id==='regioes'?'poster-photo':''}"><span>${h(m.category)}</span><div class="course-symbol" aria-hidden="true">${h(m.symbol||'◇')}</div><div class="poster-copy"><small>${ls.length?'DISPONÍVEL':'EM PRODUÇÃO'}</small><h3>${h(m.title)}</h3><small>${ls.length?ls.length+' aulas disponíveis':'Conteúdo em preparação'}</small></div></a>`;}
const trackImage=t=>t.backgroundImage?'<img class="track-background" src="'+h(t.backgroundImage)+'" alt="" loading="lazy">':'';
function home(){const tracks=byKind('track'),modules=byKind('module');const recent=byKind('lesson').filter(l=>learning['history:'+l.id]).sort((a,b)=>Number(learning['history:'+b.id])-Number(learning['history:'+a.id]))[0];const groups=[...new Set(modules.map(m=>m.category))];main.innerHTML=`<div class="container"><section class="hero"><span class="eyebrow">CONHECIMENTO PARA IR MAIS LONGE</span><h1>Seu próximo capítulo<br>começa na Itália.</h1><p>Da descoberta das suas raízes à construção de uma nova vida.<br>Encontre o caminho que faz sentido para você.</p><span class="hero-stamp">Benvenuto, ${h(user.name.split(' ')[0])}</span></section><form class="searchbar" role="search"><span>⌕</span><input id="search" aria-label="Buscar trilhas e assuntos" placeholder="O que você quer aprender hoje?"><button aria-label="Buscar">→</button></form><div id="search-results" class="hidden"></div><div id="home-content">${recent?`<div class="section-title"><h2>Continue assistindo</h2></div><section class="resume"><span class="play-small">▷</span><div><h3>${h(recent.title)}</h3><p>Retome sua jornada de aprendizado.</p></div><a class="primary" href="#aula/${h(recent.id)}">Continuar →</a></section>`:''}<div class="section-title"><div><h2>Qual é o seu próximo destino?</h2><p>Trilhas de conhecimento para cada momento da sua jornada.</p></div><span class="muted">${tracks.length} trilhas</span></div><section class="tracks">${tracks.map((t,i)=>{const p=progress(t.groups.flatMap(g=>g[1]));return `<a href="#trilha/${h(t.id)}" class="track">${trackImage(t)}<div class="topline"><span>TRILHA ${i+1}</span><span class="pill">${t.groups.flatMap(g=>g[1]).length} módulos</span></div><div class="track-info"><h3>${h(t.title)}</h3><p>${h(t.description)}</p><div class="track-link"><span>Acessar trilha →</span><span>${p.percent}%</span></div></div></a>`;}).join('')}</section>${groups.map(cat=>`<details class="catalog" open><summary>${h(cat)}</summary><div class="poster-grid">${modules.filter(m=>m.category===cat).map(poster).join('')}</div></details>`).join('')}${!modules.length?'<div class="empty"><h2>Seu conteúdo está a caminho</h2><p>Os módulos aparecerão aqui conforme forem publicados.</p></div>':''}</div></div>`;const input=document.querySelector('#search');const search=()=>{const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize(input.value.trim());document.querySelector('#home-content').classList.toggle('hidden',!!q);const box=document.querySelector('#search-results');box.classList.toggle('hidden',!q);const result=modules.filter(m=>normalize(m.title+' '+m.category).includes(q));box.innerHTML=`<div class="section-title"><h2>${result.length} assuntos encontrados</h2></div><div class="poster-grid">${result.map(poster).join('')}</div>`;};input.oninput=search;document.querySelector('.searchbar').onsubmit=e=>{e.preventDefault();search();};}
function trail(id){const t=records.find(r=>r.id===id&&r.kind==='track');if(!t)return notfound();const p=progress(t.groups.flatMap(g=>g[1]));main.innerHTML=`<div class="container narrow"><a class="back" href="#inicio">← Voltar ao início</a><section class="hero track-hero">${trackImage(t)}<span class="eyebrow">${h(t.tag)}</span><h1>${h(t.title)}</h1><p>${h(t.description)}</p></section><div class="path-head"><div><h2>Seu caminho de aprendizado</h2><small>${p.done} de ${p.total} aulas concluídas · ${p.percent}%</small></div><button class="outline" id="activate">${learning['active:track']===id?'✓ Trilha selecionada':'Selecionar trilha'}</button></div><progress max="100" value="${p.percent}" aria-label="Progresso da trilha"></progress><div class="path">${t.groups.map(([title,ids])=>`<section class="stage"><h2>${h(title)}</h2><div class="nodes">${ids.map(mid=>{const m=records.find(r=>r.id===mid);if(!m)return '';const p=progress([mid]);return `<a class="node ${p.percent===100?'done':p.total?'current':''}" href="#modulo/${h(mid)}"><span class="node-circle">${p.percent===100?'✓':p.total?'▷':'◇'}</span><strong>${h(m.title)}</strong><small>${p.total?p.percent+'% concluído':'Em produção'}</small></a>`;}).join('')}</div></section>`).join('')}</div></div>`;document.querySelector('#activate').onclick=async e=>{try{await saveLearner('active:track',id);e.target.textContent='✓ Trilha selecionada';toast('Trilha salva na sua conta.');}catch(err){toast(err.message);}};}
function modulePage(id){const m=records.find(r=>r.id===id&&r.kind==='module');if(!m)return notfound();const ls=byKind('lesson').filter(l=>l.moduleId===id);main.innerHTML=`<div class="container narrow"><a class="back" href="#inicio">← Voltar ao catálogo</a><span class="eyebrow">${h(m.category)}</span><h1 class="page-title">${h(m.title)}</h1><p class="description">${h(m.description)}</p><button id="favorite" class="outline">${learning['favorite:'+id]?'★ Remover dos favoritos':'☆ Salvar nos favoritos'}</button>${ls.length?`<div class="section-title"><h2>Aulas do módulo</h2></div><div class="table-wrap">${ls.map(l=>`<a class="lesson-row" href="#aula/${h(l.id)}"><span>${learning['complete:'+l.id]?'✓':'▷'}</span><span>${h(l.title)}<small>${l.duration?l.duration+' min':'Videoaula'}</small></span></a>`).join('')}</div>`:'<div class="empty"><span class="empty-icon">▷</span><h2>Videoaulas em produção</h2><p>As aulas deste módulo aparecerão aqui assim que forem publicadas.</p></div>'}</div>`;document.querySelector('#favorite').onclick=async()=>{try{await saveLearner('favorite:'+id,!learning['favorite:'+id]);modulePage(id);}catch(e){toast(e.message);}};}
async function lesson(id,preview=false){if(preview&&user.role!=='admin')return notfound();const source=preview?adminRecords:records;const l=source.find(r=>r.id===id&&r.kind==='lesson');if(!l)return notfound();const m=source.find(r=>r.id===l.moduleId);if(!m)return notfound();const lessons=source.filter(r=>r.kind==='lesson'&&r.moduleId===m.id&&(preview||r.status==='published')).sort(order);const p=progress([m.id]);main.innerHTML=`<div class="lesson-layout"><article class="lesson-main"><div class="crumb"><a href="#inicio">Início</a> › <a href="#modulo/${h(m.id)}">${h(m.title)}</a></div>${preview?'<div class="admin-notice">Prévia administrativa · alterações de progresso desativadas. <a href="#admin/lesson">Voltar à administração</a></div>':''}<span class="eyebrow">${h(m.category)}</span><h1>${h(l.title)}</h1><p class="description plaincopy">${h(l.description)}</p>${l.video?.type==='iframe'?`<iframe class="video-player" src="${h(l.video.url)}" title="${h(l.title)}" allow="fullscreen; picture-in-picture" allowfullscreen></iframe>`:l.video?.type==='video'?`<video class="video-player" src="${h(l.video.url)}" controls preload="metadata"></video>`:'<div class="video-empty"><span>▷</span><h2>Vídeo em preparação</h2><p>O vídeo ainda não foi cadastrado.</p></div>'}${!preview?`<div class="completion"><button id="complete" class="${learning['complete:'+id]?'outline':'primary'}">${learning['complete:'+id]?'✓ Concluída · desfazer':'Marcar aula como concluída'}</button><span class="save-state">Progresso salvo na sua conta</span></div><div class="tabs" role="tablist" aria-label="Recursos da aula">${[['tasks','Tarefas'],['notes','Minhas anotações'],['questions','Dúvidas']].map(([v,t],i)=>`<button role="tab" id="tab-${v}" aria-controls="panel" data-tab="${v}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${t}</button>`).join('')}</div><div id="panel" class="tabcontent" role="tabpanel"></div>`:''}<div class="lesson-end"><a class="back" href="#modulo/${h(m.id)}">← Ver módulo</a>${lessons[lessons.indexOf(l)+1]?`<a class="outline" href="#${preview?'preview':'aula'}/${h(lessons[lessons.indexOf(l)+1].id)}">Próxima aula →</a>`:''}</div></article><aside class="lesson-sidebar"><h2>${h(m.title)}</h2><small>PROGRESSO DO MÓDULO</small><progress value="${p.percent}" max="100" aria-label="Progresso do módulo"></progress><p class="muted">${p.done} de ${p.total} aulas concluídas</p><details open><summary>AULAS</summary>${lessons.map(a=>`<a class="lesson-row ${a.id===id?'selected':''}" href="#${preview?'preview':'aula'}/${h(a.id)}">${learning['complete:'+a.id]?'✓':'▷'} <span>${h(a.title)}<small>${a.duration?a.duration+' min':''}${preview?' · '+statusName[a.status]:''}</small></span></a>`).join('')}</details></aside></div>`;
 if(preview)return;saveLearner('history:'+id,Date.now()).catch(e=>toast(e.message));document.querySelector('#complete').onclick=async e=>{const btn=e.target;btn.disabled=true;try{await saveLearner('complete:'+id,!learning['complete:'+id]);await lesson(id);}catch(err){toast(err.message);btn.disabled=false;}};
 let tabVersion=0;async function tab(which){const version=++tabVersion;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===which));b.tabIndex=b.dataset.tab===which?0:-1;});const panel=document.querySelector('#panel');panel.setAttribute('aria-labelledby','tab-'+which);if(which==='tasks'){panel.innerHTML=l.tasks?.length?`<h3>Coloque em prática</h3>${l.tasks.map(t=>`<label class="task"><input type="checkbox" data-task="${h(t.id)}" ${learning['task:'+t.id]?'checked':''}><span>${h(t.title)}</span></label>`).join('')}`:'<p class="muted">Esta aula não tem tarefas complementares.</p>';panel.querySelectorAll('[data-task]').forEach(input=>input.onchange=async()=>{input.disabled=true;try{await saveLearner('task:'+input.dataset.task,input.checked);}catch(e){input.checked=!input.checked;toast(e.message);}finally{input.disabled=false;}});}else if(which==='notes'){panel.innerHTML=`<form id="note-form" class="form">${area('Minhas anotações','note',learning['note:'+id]||'')}<small>Estas anotações são privadas e vinculadas à sua conta.</small>${errorBox}<div><button type="submit" class="primary">Salvar anotações</button></div></form>`;attachForm('note-form',async b=>{await saveLearner('note:'+id,b.note);toast('Anotações salvas.');});}else{panel.innerHTML='<p class="muted">Carregando suas dúvidas…</p>';try{const result=await api('/questions');if(version!==tabVersion||!panel.isConnected)return;panel.innerHTML=`<form class="form" id="question-form">${area('Envie sua dúvida','text')}${errorBox}<div><button type="submit" class="primary">Enviar dúvida</button></div></form><h3>Minhas dúvidas</h3>${result.questions.filter(q=>q.lessonId===id).map(q=>`<div class="question">${h(q.text)}${q.answer?`<div class="answer"><strong>Resposta da equipe</strong><br>${h(q.answer)}</div>`:'<p class="muted">Aguardando resposta</p>'}</div>`).join('')}`;attachForm('question-form',async b=>{await api('/questions','POST',{lessonId:id,text:b.text});tab('questions');});}catch(e){panel.textContent=e.message;}}}
 document.querySelectorAll('[data-tab]').forEach((b,i)=>{b.onclick=()=>tab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const bs=[...document.querySelectorAll('[data-tab]')],n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;bs[n].focus();tab(bs[n].dataset.tab);};});tab('tasks');}
function collection(kind){let modules;if(kind==='favoritos')modules=byKind('module').filter(m=>learning['favorite:'+m.id]);else{const seen=byKind('lesson').filter(l=>learning['history:'+l.id]).sort((a,b)=>learning['history:'+b.id]-learning['history:'+a.id]);modules=[...new Set(seen.map(l=>l.moduleId))].map(id=>records.find(r=>r.id===id)).filter(Boolean);}main.innerHTML=`<div class="container"><h1 class="page-title">${kind==='favoritos'?'Favoritos':'Histórico'}</h1><p class="muted">Seus conteúdos, salvos na sua conta.</p>${modules.length?`<div class="poster-grid">${modules.map(poster).join('')}</div>`:'<div class="empty"><h2>Ainda não há conteúdos aqui</h2><p>Explore os módulos para começar.</p><a class="primary" href="#inicio">Ver catálogo</a></div>'}</div>`;}

const plannerStatuses={not_started:'Não iniciado',organizing:'Organizando',waiting:'Aguardando',in_progress:'Em andamento',blocked:'Bloqueado',done:'Concluído'};
const plannerStatusOptions=Object.entries(plannerStatuses);
const plannerDefaultItem=(id,title,phase)=>({id,title,phase,status:'not_started',responsible:'',issuanceDate:'',dueDate:'',cost:'',currency:'EUR',priority:'normal',documentNumber:'',location:'',notes:'',description:'',requiredDocuments:'',attachmentRequired:false,updated:0});
function plannerData(track,template){
 const saved=learning['planner:'+track.id]||{};
 const old=new Map((saved.items||[]).map(item=>[item.id,item]));
 const items=[];
 if(template?.items?.length){for(const task of template.items){items.push({...plannerDefaultItem(task.id,task.title,task.phase),responsible:task.responsibleHint||'',cost:task.estimatedCost??'',currency:task.currency||'EUR',priority:task.priority||'normal',description:task.description||'',requiredDocuments:task.requiredDocuments||'',attachmentRequired:!!task.attachmentRequired,...(old.get(task.id)||{}),id:task.id,title:task.title,phase:task.phase});}}else for(const [phase,ids] of track.groups){for(const id of ids){const module=records.find(r=>r.kind==='module'&&r.id===id);if(!module)continue;items.push({...plannerDefaultItem(id,module.title,phase),...(old.get(id)||{}),id,title:module.title,phase});}}
 return{trackId:track.id,items,updated:saved.updated||0};
}
async function savePlanner(plan,message='Planner atualizado.'){
 plan.updated=Date.now();
 await api('/learner','PUT',{key:'planner:'+plan.trackId,value:plan});
 learning['planner:'+plan.trackId]=structuredClone(plan);
 toast(message);
}
async function planner(){
 const tracks=byKind('track');
 if(!tracks.length){main.innerHTML='<div class="container"><div class="empty"><h1>Meu Planner</h1><p>Seu planner ficará disponível assim que uma trilha for publicada.</p></div></div>';return;}
 const requested=new URLSearchParams(location.hash.split('?')[1]||'').get('trilha');
 const active=tracks.find(t=>t.id===(requested||learning['active:track']))||tracks[0];
 const template=records.find(r=>r.kind==='planner'&&r.trackId===active.id),plan=plannerData(active,template);let plannerAttachments=[];try{plannerAttachments=(await api('/planner/attachments?track='+encodeURIComponent(active.id))).attachments;}catch(e){toast(e.message);}
 const completed=plan.items.filter(i=>i.status==='done').length;
 const blocked=plan.items.filter(i=>i.status==='blocked').length;
 const totalEUR=plan.items.filter(i=>i.currency!=='BRL').reduce((sum,i)=>sum+(Number(i.cost)||0),0),totalBRL=plan.items.filter(i=>i.currency==='BRL').reduce((sum,i)=>sum+(Number(i.cost)||0),0);
 const percent=plan.items.length?Math.round(completed/plan.items.length*100):0;
 const phases=[...new Set(plan.items.map(i=>i.phase))];
 const money=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'EUR'}).format(totalEUR)+(totalBRL?' + '+new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(totalBRL):'');
 main.innerHTML=`<div class="planner-page"><section class="planner-hero"><div><span class="eyebrow">IL MIO PERCORSO</span><h1>Meu Planner Itália</h1><p>Organize documentos, prazos e decisões da sua jornada em um só lugar.</p></div><div class="planner-stamp"><strong>${percent}%</strong><span>da jornada concluída</span></div></section><section class="planner-controls"><label>Trilha do planner<select id="planner-track">${tracks.map(t=>`<option value="${h(t.id)}" ${t.id===active.id?'selected':''}>${h(t.title)}</option>`).join('')}</select></label><label>Filtrar por status<select id="planner-filter"><option value="">Todos os status</option>${plannerStatusOptions.map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label>Buscar etapa<input id="planner-search" placeholder="Documento, responsável..."></label></section><section class="planner-summary"><article><span>Progresso geral</span><strong>${completed}/${plan.items.length}</strong><progress value="${percent}" max="100" aria-label="Progresso do planner"></progress></article><article><span>Em atenção</span><strong>${blocked}</strong><small>itens bloqueados</small></article><article><span>Custos previstos</span><strong>${money}</strong><small>valores informados no planner</small></article><article><span>Próximo prazo</span><strong>${h(nextPlannerDue(plan.items)||'A definir')}</strong><small>data mais próxima</small></article></section><div class="planner-toolbar"><div><h2>Etapas do processo</h2><p>Cada etapa acompanha um módulo da trilha selecionada.</p></div><button class="outline" id="planner-expand">Expandir todas</button></div><div id="planner-phases">${phases.map((phase,index)=>plannerPhase(phase,plan.items.filter(i=>i.phase===phase),index,plannerAttachments)).join('')}</div><div class="planner-footnote">🔒 As informações deste planner são privadas e vinculadas à sua conta.</div></div>`;
 const renderFilter=()=>{const status=document.querySelector('#planner-filter').value,q=document.querySelector('#planner-search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelectorAll('.planner-item').forEach(card=>{const item=plan.items.find(i=>i.id===card.dataset.item);const hay=(item.title+' '+item.responsible+' '+item.documentNumber+' '+item.notes).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();card.classList.toggle('hidden',!!status&&item.status!==status||!!q&&!hay.includes(q));});document.querySelectorAll('.planner-phase').forEach(group=>group.classList.toggle('hidden',![...group.querySelectorAll('.planner-item')].some(x=>!x.classList.contains('hidden'))));};
 document.querySelector('#planner-track').onchange=e=>{location.hash='planner?trilha='+encodeURIComponent(e.target.value);};
 document.querySelector('#planner-filter').onchange=renderFilter;document.querySelector('#planner-search').oninput=renderFilter;
 let expanded=false;document.querySelector('#planner-expand').onclick=e=>{expanded=!expanded;document.querySelectorAll('.planner-item').forEach(d=>d.open=expanded);e.target.textContent=expanded?'Recolher todas':'Expandir todas';};
 document.querySelectorAll('.planner-item').forEach(card=>{const item=plan.items.find(i=>i.id===card.dataset.item),fileInput=card.querySelector('[data-attachment-input]');fileInput.onchange=async()=>{const files=[...fileInput.files];if(!files.length)return;if(plannerAttachments.filter(a=>a.itemId===item.id).length+files.length>5){toast('Cada etapa aceita até cinco anexos.');fileInput.value='';return;}card.querySelector('.planner-upload').classList.add('uploading');try{for(const file of files){if(file.size>2*1024*1024)throw Error(file.name+': o arquivo deve ter até 2 MB.');if(!['application/pdf','image/jpeg','image/png','image/webp'].includes(file.type))throw Error(file.name+': formato não permitido.');const data=await fileDataUrl(file);await api('/planner/attachments','POST',{trackId:plan.trackId,itemId:item.id,name:file.name,data});}toast(files.length>1?'Anexos enviados.':'Anexo enviado.');await planner();}catch(err){toast(err.message);card.querySelector('.planner-upload').classList.remove('uploading');fileInput.value='';}};card.querySelectorAll('[data-delete-attachment]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/planner/attachments/'+button.dataset.deleteAttachment,'DELETE',{});toast('Anexo removido.');await planner();}catch(err){toast(err.message);button.disabled=false;}});const form=card.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;const data=Object.fromEntries(new FormData(form));Object.assign(item,data,{updated:Date.now()});try{await savePlanner(plan);planner();}catch(err){toast(err.message);submit.disabled=false;}};card.querySelector('[name="status"]').onchange=e=>{card.dataset.status=e.target.value;card.querySelector('.planner-status').className='planner-status '+e.target.value;card.querySelector('.planner-status').textContent=plannerStatuses[e.target.value];};});
}
const fileDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});
function nextPlannerDue(items){const dates=items.filter(i=>i.status!=='done'&&i.dueDate&&Date.parse(i.dueDate)>=Date.now()-86400000).map(i=>i.dueDate).sort();return dates[0]?new Date(dates[0]+'T12:00:00').toLocaleDateString('pt-BR'):'';}
function plannerPhase(phase,items,index,attachments){const done=items.filter(i=>i.status==='done').length;return `<section class="planner-phase"><div class="planner-phase-head"><span>${String(index+1).padStart(2,'0')}</span><div><h3>${h(phase)}</h3><small>${done} de ${items.length} etapas concluídas</small></div><progress value="${done}" max="${items.length||1}" aria-label="Progresso de ${h(phase)}"></progress></div><div class="planner-list">${items.map(item=>plannerItem(item,attachments.filter(a=>a.itemId===item.id))).join('')}</div></section>`;}
function plannerItem(item,attachments=[]){const files=attachments.length?`<div class="planner-files">${attachments.map(a=>`<div class="planner-file-row"><span aria-hidden="true">${a.type==='application/pdf'?'PDF':'IMG'}</span><a href="/api/planner/attachments/${h(a.id)}" target="_blank" rel="noopener">${h(a.name)}</a><small>${(a.size/1024).toFixed(0)} KB</small><a class="outline" href="/api/planner/attachments/${h(a.id)}?download=1" download>Baixar</a><button type="button" class="attachment-delete" data-delete-attachment="${h(a.id)}" aria-label="Remover ${h(a.name)}">×</button></div>`).join('')}</div>`:'<p class="planner-no-files">Nenhum anexo enviado nesta etapa.</p>';return `<details class="planner-item" data-item="${h(item.id)}" data-status="${h(item.status)}"><summary><span class="planner-check">${item.status==='done'?'✓':'○'}</span><span class="planner-item-title"><strong>${h(item.title)}</strong><small>${h(item.responsible||'Responsável não definido')}${item.dueDate?' · prazo '+h(new Date(item.dueDate+'T12:00:00').toLocaleDateString('pt-BR')):''}</small></span><span class="planner-status ${h(item.status)}">${h(plannerStatuses[item.status]||plannerStatuses.not_started)}</span><span class="planner-chevron">⌄</span></summary><form class="planner-form"><div class="planner-form-grid"><label>Status<select name="status">${plannerStatusOptions.map(([v,n])=>`<option value="${v}" ${item.status===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Responsável<input name="responsible" value="${h(item.responsible)}" maxlength="120" placeholder="Você, consultor, familiar..."></label><label>Prioridade<select name="priority"><option value="low" ${item.priority==='low'?'selected':''}>Baixa</option><option value="normal" ${item.priority==='normal'?'selected':''}>Normal</option><option value="high" ${item.priority==='high'?'selected':''}>Alta</option></select></label><label>Data de emissão<input name="issuanceDate" type="date" value="${h(item.issuanceDate)}"></label><label>Prazo / validade<input name="dueDate" type="date" value="${h(item.dueDate)}"></label><label>Custo / taxas<div class="money-field"><select name="currency"><option value="EUR" ${item.currency==='EUR'?'selected':''}>EUR</option><option value="BRL" ${item.currency==='BRL'?'selected':''}>BRL</option></select><input name="cost" type="number" min="0" max="9999999" step="0.01" value="${h(item.cost)}" placeholder="0,00"></div></label><label>Número / protocolo<input name="documentNumber" value="${h(item.documentNumber)}" maxlength="120" placeholder="Protocolo, comune, codice..."></label><label>Local / órgão responsável<input name="location" value="${h(item.location)}" maxlength="160" placeholder="Consulado, comune, cartório..."></label></div>${item.description?`<div class="planner-guidance"><strong>Orientação da administração</strong><p>${h(item.description)}</p>${item.requiredDocuments?`<small><b>Documentos previstos:</b> ${h(item.requiredDocuments)}</small>`:''}</div>`:''}<section class="planner-upload ${item.attachmentRequired?'required':''}"><div><strong>Arquivos e anexos ${item.attachmentRequired?'<span class="required-mark">Obrigatório</span>':''}</strong><small>PDF, JPG, PNG ou WebP · até 2 MB cada · máximo de 5 arquivos</small></div><label class="outline attachment-picker">+ Enviar arquivo<input type="file" data-attachment-input accept="application/pdf,image/jpeg,image/png,image/webp" multiple hidden></label></section>${files}<label class="planner-notes">Notas e próximos passos<textarea name="notes" maxlength="5000" placeholder="Pendências, contatos, observações e próximos passos...">${h(item.notes)}</textarea></label><div class="planner-actions"><span>${item.updated?'Atualizado em '+h(new Date(item.updated).toLocaleString('pt-BR')):'Ainda não preenchido'}</span><button class="primary" type="submit">Salvar etapa</button></div></form></details>`;}

async function agenda(){
 main.innerHTML='<div class="container narrow"><h1 class="page-title">Agenda</h1><p class="muted">Encontros ao vivo, reuniões com prestadores e datas importantes.</p><div class="tabs"><button id="upcoming" aria-pressed="true">Próximos</button><button id="past" aria-pressed="false">Passados</button></div><div id="events"><p class="muted">Carregando agenda…</p></div></div>';
 let bookings=[];try{bookings=(await api('/bookings')).bookings;}catch(e){toast(e.message);}
 const set=past=>{document.querySelector('#upcoming').setAttribute('aria-pressed',String(!past));document.querySelector('#past').setAttribute('aria-pressed',String(past));const events=byKind('event').filter(e=>(new Date(e.end)<new Date())===past).sort((a,b)=>past?Date.parse(b.start)-Date.parse(a.start):Date.parse(a.start)-Date.parse(b.start));const meetings=bookings.filter(b=>['requested','confirmed'].includes(b.status)&&(new Date(b.start)<new Date())===past).sort((a,b)=>past?Date.parse(b.start)-Date.parse(a.start):Date.parse(a.start)-Date.parse(b.start));const rows=[...meetings.map(b=>`<article class="event-row provider-agenda-row"><div class="date">${h(date(b.start))}</div><div><span class="status ${h(b.status)}">${b.status==='confirmed'?'Confirmada':'Aguardando prestador'}</span><h2>Reunião com ${h(b.provider)}</h2><small>${b.duration} minutos · ${h(new Intl.NumberFormat('pt-BR',{style:'currency',currency:b.currency}).format(b.price))} · pagamento ${h(b.payment_status)}</small><p class="muted plaincopy">${h(b.message)}</p></div>${b.status==='confirmed'&&b.meeting_url?`<a class="primary" href="${h(b.meeting_url)}" target="_blank" rel="noopener">Entrar na reunião ↗</a>`:''}</article>`),...events.map(e=>`<article class="event-row"><div class="date">${h(date(e.start))}</div><div><h2>${h(e.title)}</h2><small>${h(e.host)}</small><p class="muted plaincopy">${h(e.description)}</p><p class="muted">${h(e.location)}</p></div>${e.joinUrl?`<a class="outline" href="${h(e.joinUrl)}" target="_blank" rel="noopener noreferrer">${past?'Abrir link':'Acessar encontro'} ↗</a>`:''}</article>`)];document.querySelector('#events').innerHTML=rows.length?rows.join(''):'<div class="empty"><h2>Nenhum encontro neste período</h2><p>A programação será atualizada pela equipe.</p></div>';};document.querySelector('#upcoming').onclick=()=>set(false);document.querySelector('#past').onclick=()=>set(true);set(false);
}
function profile(){main.innerHTML=`<div class="container narrow"><div class="profile-avatar">${h(user.name.charAt(0))}</div><h1 class="page-title">Meu perfil</h1><p class="muted">${h(user.email)} · ${user.role==='admin'?'Administrador':'Aluno'}</p><div class="profile-grid"><section class="editor"><h2>Seus dados</h2><form class="form" id="profile-form">${field('Nome','name',user.name,'text',true)}${errorBox}<button class="primary" type="submit">Salvar perfil</button></form></section><section class="editor"><h2>Alterar senha</h2><form class="form" id="password-form"><label>Senha atual<input type="password" name="current" autocomplete="current-password" required></label>${field('Nova senha','password','','password',true)}<small>Pelo menos 12 caracteres. As outras sessões serão encerradas.</small>${errorBox}<button type="submit" class="primary">Alterar senha</button></form></section>${accessSummary()}</div></div>`;if(user.role!=='admin')buyOptions(document.querySelector('#buy-options'));attachForm('profile-form',async b=>{await api('/profile','PUT',b);({user,access}=await api('/auth/me'));frame();toast('Perfil atualizado.');});attachForm('password-form',async(b,form)=>{await api('/password','PUT',b);form.reset();toast('Senha alterada.');});}
function authPage(){const token=new URLSearchParams(location.hash.split('?')[1]||'').get('token');const mode=location.hash.startsWith('#ativar')?'activate':'login';main.innerHTML=`<div class="auth-shell"><a class="brandtext" href="#entrar">Arrivo In Itália ↗</a><h1>${mode==='activate'?'Defina seu acesso':'Bem-vindo de volta'}</h1><p class="muted">${mode==='activate'?'Use o link recebido da administração para definir sua senha.':'Entre na sua conta para continuar sua jornada.'}</p><form id="auth-form" class="form">${mode==='login'?field('E-mail','email','','email',true):field('Seu nome','name','','text',true)}<label>Senha<input name="password" type="password" ${mode==='login'?'autocomplete="current-password"':'autocomplete="new-password" minlength="12" maxlength="72"'} required></label>${mode!=='login'?'<small>Use pelo menos 12 caracteres e guarde sua senha em um local seguro.</small>':''}${errorBox}<button class="primary" type="submit">${mode==='login'?'Entrar':'Definir senha'}</button></form><p class="help">${mode==='login'?'Ainda não é aluno? <a href="/">Conheça o curso</a>. Para recuperar a senha, solicite um novo link à equipe.':'O link de acesso é pessoal e não deve ser compartilhado.'}</p></div>`;attachForm('auth-form',async b=>{const result=await api('/auth/'+mode,'POST',mode==='activate'?{...b,token}:b);if(mode==='activate'){goto('entrar');toast('Senha definida. Entre com seu e-mail.');return;}user=result.user;access=result.access;if(can('course'))await loadCatalog();frame();goto(user.role==='admin'?'admin':'inicio');render();});}
const menu=[['','Visão geral'],['track','Trilhas'],['module','Módulos'],['lesson','Aulas'],['planner','Gestão do Planner'],['provider','Prestadores'],['bookings','Reuniões'],['event','Agenda'],['users','Alunos e acessos'],['sales','Vendas'],['questions','Dúvidas'],['audit','Registro de ações']];
function adminShell(section,title,description,content,action=''){
 main.innerHTML=`<div class="management"><section><div class="admin-head"><div><h1>${h(title)}</h1><p>${h(description)}</p></div>${action}</div>${content}</section></div>`;
}

async function admin(section='',id){if(user.role!=='admin'){main.innerHTML='<div class="empty"><h1>Acesso restrito</h1><p>Esta área é exclusiva da administração.</p><a href="#inicio">Voltar</a></div>';return;}adminRecords=(await api('/admin/records')).records;if(!section){const stats=[['Trilhas','track'],['Módulos','module'],['Aulas','lesson'],['Eventos','event']];adminShell('','Visão geral','Gerencie o conteúdo e acompanhe a operação do Arrivo In Itália.',`<div class="metrics">${stats.map(([name,kind])=>`<a class="metric" href="#admin/${kind}"><strong>${adminRecords.filter(r=>r.kind===kind&&r.status!=='archived').length}</strong><span>${name}</span></a>`).join('')}<a class="metric" href="#admin/questions"><strong>${adminRecords.filter(r=>r.kind==='question'&&r.status==='open').length}</strong><span>Dúvidas aguardando resposta</span></a><div class="metric"><strong>${adminRecords.filter(r=>r.kind==='lesson'&&r.status==='published').length}</strong><span>Aulas publicadas</span></div></div><div class="editor"><h2>Seu fluxo de publicação</h2><p class="help">1. Cadastre um módulo para agrupar as aulas.<br>2. Insira as aulas com vídeo, descrição e tarefas.<br>3. Organize os módulos em etapas de uma trilha.<br>4. Publique os conteúdos quando estiverem prontos.</p><p class="help">As aulas em rascunho e os conteúdos arquivados não aparecem para os alunos. A área do aluno sempre exibe apenas o conteúdo publicado, inclusive quando você a acessa como administrador.</p></div>`);return;}
 if(section==='planner')return plannerAdmin(id);if(section==='bookings')return bookingsAdmin();
 if(section==='users')return usersPage();if(section==='sales')return salesAdmin();if(section==='audit'){const {entries}=await api('/admin/audit');adminShell(section,'Registro de ações','Últimas 100 alterações administrativas.',`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Responsável</th><th>Ação</th><th>Registro</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${h(date(e.created*1000))}</td><td>${h(e.actorName||e.actor)}</td><td>${h(e.action)}</td><td>${h(e.target)}</td></tr>`).join('')}</tbody></table></div>`);return;}
 if(section==='questions')return questionsAdmin(id);
 if(!['track','module','lesson','provider','event'].includes(section))return notfound();if(id)return editor(section,id);
 const titles={track:'Trilhas',module:'Módulos',lesson:'Aulas',provider:'Prestadores',event:'Agenda'};adminShell(section,titles[section],'Crie, edite, publique ou arquive os registros.',`<div class="admin-toolbar"><input id="admin-search" aria-label="Buscar registros" placeholder="Buscar por título…"><select id="admin-filter" aria-label="Filtrar estado"><option value="all">Todos os estados</option><option value="published">Publicados</option><option value="draft">Rascunhos</option><option value="archived">Arquivados</option></select></div><div id="admin-list"></div>`,`<a class="primary" href="#admin/${section}/new">+ ${section==='event'?'Novo evento':section==='module'?'Novo módulo':section==='lesson'?'Nova aula':section==='provider'?'Novo prestador':'Nova trilha'}</a>`);const list=()=>{const query=document.querySelector('#admin-search').value.toLowerCase(),status=document.querySelector('#admin-filter').value;const rows=adminRecords.filter(r=>r.kind===section&&(status==='all'||r.status===status)&&r.title.toLowerCase().includes(query)).sort(order);document.querySelector('#admin-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Título</th><th>Estado</th><th>Ordem</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${h(r.title)}${section==='lesson'?`<small>${h(adminRecords.find(m=>m.id===r.moduleId)?.title||'')}</small>`:''}${section==='event'?`<small>${h(date(r.start))}</small>`:''}</td><td>${badge(r.status)}</td><td>${r.order||0}</td><td><a class="outline" href="#admin/${section}/${h(r.id)}">Editar</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Nenhum registro encontrado</h2><p>Crie um registro ou ajuste os filtros.</p></div>';};document.querySelector('#admin-search').oninput=list;document.querySelector('#admin-filter').onchange=list;list();}
function localDate(s){if(!s)return '';const d=new Date(s);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function editor(kind,id){const old=id==='new'?null:adminRecords.find(r=>r.id===id&&r.kind===kind);if(id!=='new'&&!old)return notfound();const r=old||{title:'',description:'',status:'draft',order:0,groups:[],tasks:[]};const names={track:'trilha',module:'módulo',lesson:'aula',provider:'prestador',event:'evento'};const modules=adminRecords.filter(r=>r.kind==='module'&&r.status!=='archived').sort(order);const common=`${field('Título','title',r.title,'text',true)}${area('Descrição','description',r.description)}<div class="row">${select('Estado','status',[['draft','Rascunho'],['published','Publicado'],['archived','Arquivado']],r.status)}${field('Ordem de exibição','order',r.order,'number')}</div>`;let backgroundImage=r.backgroundImage||'';let imagePending=false;let fields='';if(kind==='module')fields=`<div class="row">${field('Categoria','category',r.category||'CURSOS','text',true)}${field('Símbolo do cartão','symbol',r.symbol||'◇')}</div>`;if(kind==='lesson')fields=`${select('Módulo','moduleId',modules.map(m=>[m.id,m.title]),r.moduleId||modules[0]?.id)}${field('Link do vídeo','videoUrl',r.videoUrl||'','url')}<small>YouTube, Vimeo ou link HTTPS de um arquivo MP4. O vídeo é necessário para publicar a aula.</small>${field('Duração em minutos','duration',r.duration||0,'number')}${area('Tarefas (uma por linha)','tasks',(r.tasks||[]).map(t=>t.title).join('\n'))}${old?`<a class="outline" href="#preview/${h(id)}">Ver prévia da aula</a>`:''}`;

 if(kind==='provider')fields=`<fieldset class="track-image-editor"><legend>Foto do prestador</legend><div id="image-preview"></div><input id="provider-image-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="form-actions"><button type="button" class="outline" id="choose-image">${r.photo?'Alterar foto':'Inserir foto'}</button><button type="button" class="outline" id="remove-image">Remover foto</button></div><small>JPG, PNG ou WebP, até 500 KB.</small><p id="image-error" role="alert"></p></fieldset>${field('Empresa / marca','brand',r.brand||'')}${field('Especialidade','specialty',r.specialty||'','text',true)}${area('Resumo do card','summary',r.summary||'')}${area('Biografia e apresentação','bio',r.bio||'')}${area('Serviços oferecidos','services',r.services||'')}${area('Formação e credenciais','credentials',r.credentials||'')}<div class="row">${field('Preço da reunião','price',r.price??0,'number',true)}${select('Moeda','currency',[['EUR','EUR'],['BRL','BRL']],r.currency||'EUR')}</div><div class="row">${field('Duração em minutos','duration',r.duration||60,'number',true)}${field('Cidade / região','city',r.city||'')}</div><div class="row">${field('Avaliação média (0 a 5)','rating',r.rating??0,'number')}${field('Quantidade de avaliações','reviewCount',r.reviewCount??0,'number')}</div><label class="planner-required-toggle"><input type="checkbox" name="featured" ${r.featured?'checked':''}> Destacar este prestador no catálogo</label>${field('Idiomas','languages',r.languages||'')}${field('E-mail de contato','email',r.email||'','email',true)}${field('Telefone / WhatsApp','phone',r.phone||'')}${field('Site HTTPS','website',r.website||'','url')}${area('Disponibilidade e observações de agenda','availability',r.availability||'')}`;
 if(kind==='event')fields=
`<div class="row">${field('Início','start',localDate(r.start),'datetime-local',true)}${field('Término','end',localDate(r.end),'datetime-local',true)}</div><small>Horários em ${h(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Cada aluno verá no próprio fuso.</small>${field('Responsável pelo encontro','host',r.host||'')}${field('Local ou plataforma','location',r.location||'')}${field('Link do encontro','joinUrl',r.joinUrl||'','url')}`;
 if(kind==='track')fields=`<fieldset class="track-image-editor"><legend>Imagem de fundo</legend><div id="image-preview"></div><input id="track-image-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="form-actions"><button type="button" class="outline" id="choose-image">${backgroundImage?'Alterar imagem':'Inserir imagem'}</button><button type="button" class="outline" id="remove-image">Usar imagem padrão</button></div><small>JPG, PNG ou WebP, até 500 KB. Prefira uma imagem horizontal. A alteração será aplicada ao salvar a trilha.</small><p id="image-error" role="alert"></p></fieldset>${field('Texto curto do banner','tag',r.tag||'SUA JORNADA')}<div><h3>Etapas e módulos</h3><p class="help">Crie as etapas na sequência desejada. Marque os módulos e use os números para ordenar cada etapa.</p><div id="sections"></div><button type="button" class="outline" id="add-section">+ Adicionar etapa</button></div>`;
 adminShell(kind,(old?'Editar ':'Criar ')+names[kind],'As alterações só serão aplicadas ao salvar.',`<section class="editor"><form class="form" id="editor-form">${common}${fields}${errorBox}<div class="form-actions"><button class="primary" type="submit">Salvar ${names[kind]}</button><a class="outline" href="#admin/${kind}">Cancelar</a></div></form></section>`);
 let groups=structuredClone(r.groups||[]);function drawGroups(){const root=document.querySelector('#sections');root.innerHTML=groups.map((g,i)=>`<div class="section-builder" data-section="${i}"><div class="section-heading"><input data-section-name value="${h(g[0])}" aria-label="Nome da etapa ${i+1}" required><button type="button" data-up="${i}" class="outline" ${i===0?'disabled':''} aria-label="Mover etapa para cima">↑</button><button type="button" data-remove="${i}" class="outline danger" aria-label="Remover etapa">×</button></div><div class="module-options">${modules.map((m,mi)=>`<div class="module-choice"><input type="checkbox" data-mid="${h(m.id)}" aria-label="Incluir ${h(m.title)}" ${g[1].includes(m.id)?'checked':''}><span>${h(m.title)}</span><input type="number" data-order-for="${h(m.id)}" min="0" value="${g[1].includes(m.id)?g[1].indexOf(m.id):mi}" aria-label="Ordem de ${h(m.title)}"></div>`).join('')}</div></div>`).join('');root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{collectGroups();groups.splice(Number(b.dataset.remove),1);drawGroups();});root.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{collectGroups();const i=Number(b.dataset.up);[groups[i-1],groups[i]]=[groups[i],groups[i-1]];drawGroups();});}
 function collectGroups(){groups=[...document.querySelectorAll('[data-section]')].map(section=>[section.querySelector('[data-section-name]').value,[...section.querySelectorAll('[data-mid]:checked')].map(el=>({id:el.dataset.mid,order:Number([...section.querySelectorAll('[data-order-for]')].find(x=>x.dataset.orderFor===el.dataset.mid).value)})).sort((a,b)=>a.order-b.order).map(x=>x.id)]);}

 if(kind==='provider'){let photo=r.photo||'';const preview=()=>{document.querySelector('#image-preview').innerHTML=photo?`<img class="provider-photo-preview" src="${h(photo)}" alt="Prévia da foto">`:'<div class="provider-photo-placeholder">Foto do prestador</div>';};preview();const input=document.querySelector('#provider-image-file');document.querySelector('#choose-image').onclick=()=>input.click();document.querySelector('#remove-image').onclick=()=>{photo='';preview();};input.onchange=async()=>{const file=input.files[0];if(!file)return;const error=document.querySelector('#image-error');error.textContent='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>500*1024)throw Error('Selecione JPG, PNG ou WebP de até 500 KB.');photo=await fileDataUrl(file);preview();}catch(e){error.textContent=e.message;}input.value='';};r.__providerPhoto=()=>photo;}
 if(kind==='track'){
 const preview=
()=>{document.querySelector('#image-preview').innerHTML='<div class="track image-preview">'+trackImage({backgroundImage})+'<div class="track-info"><h3>'+h(document.querySelector('[name="title"]').value||'Prévia da trilha')+'</h3></div></div>';document.querySelector('#choose-image').textContent=backgroundImage?'Alterar imagem':'Inserir imagem';};
 preview();document.querySelector('[name="title"]').addEventListener('input',preview);
 const input=document.querySelector('#track-image-file');
 document.querySelector('#choose-image').onclick=()=>input.click();
 document.querySelector('#remove-image').onclick=()=>{backgroundImage='';preview();};
 input.onchange=async()=>{const file=input.files[0];if(!file)return;const error=document.querySelector('#image-error');error.textContent='';imagePending=true;document.querySelector('#choose-image').disabled=true;document.querySelector('#remove-image').disabled=true;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>500*1024)throw Error('Selecione JPG, PNG ou WebP de até 500 KB.');const image=await createImageBitmap(file);image.close();backgroundImage=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});preview();}catch(e){error.textContent=e.message||'Imagem inválida.';}finally{imagePending=false;input.value='';document.querySelector('#choose-image').disabled=false;document.querySelector('#remove-image').disabled=false;}};
 drawGroups();document.querySelector('#add-section').onclick=()=>{collectGroups();groups.push(['Nova etapa',[]]);drawGroups();};}
 attachForm('editor-form',async b=>{b.kind=kind;b.order=Number(b.order);if(old)b.revision=old.revision;if(kind==='provider'){b.price=Number(b.price);b.duration=Number(b.duration);b.rating=Number(b.rating);b.reviewCount=Number(b.reviewCount);b.featured=b.featured==='on';b.photo=r.__providerPhoto?r.__providerPhoto():r.photo||'';}if(kind==='track'){if(imagePending)throw Error('Aguarde a leitura da imagem.');collectGroups();b.groups=groups;b.backgroundImage=backgroundImage;}if(kind==='lesson'){b.duration=Number(b.duration);b.tasks=b.tasks.split('\n').map(s=>s.trim()).filter(Boolean).map(title=>({id:(r.tasks||[]).find(t=>t.title===title)?.id||crypto.randomUUID(),title}));}if(kind==='event'){b.start=new Date(b.start).toISOString();b.end=new Date(b.end).toISOString();}await api('/admin/records'+(old?'/'+id:''),old?'PUT':'POST',b);await loadCatalog();toast('Conteúdo salvo.');goto('admin/'+kind);});}

function plannerTemplateFor(track){return adminRecords.find(r=>r.kind==='planner'&&r.trackId===track.id);}
function defaultPlannerTasks(track){const items=[];for(const [phase,ids] of track.groups||[])for(const id of ids){const module=adminRecords.find(r=>r.kind==='module'&&r.id===id);if(module)items.push({id:crypto.randomUUID(),title:module.title,phase,description:module.description||'',responsibleHint:'',priority:'normal',estimatedCost:'',currency:'EUR',dueDays:'',requiredDocuments:'',attachmentRequired:false,order:items.length});}return items;}
function plannerAdmin(trackId){const tracks=adminRecords.filter(r=>r.kind==='track'&&r.status!=='archived').sort(order);if(!trackId){adminShell('planner','Gestão do Planner','Defina as etapas práticas que os alunos preencherão em cada trilha.',tracks.length?`<div class="planner-admin-grid">${tracks.map(track=>{const template=plannerTemplateFor(track);return `<article class="planner-admin-card"><span class="status ${template?.status||'draft'}">${template?statusName[template.status]:'Não configurado'}</span><h2>${h(track.title)}</h2><p>${h(track.description)}</p><div><strong>${template?.items?.length||0}</strong><small> tarefas configuradas</small></div><a class="primary" href="#admin/planner/${h(track.id)}">${template?'Editar modelo':'Configurar planner'} →</a></article>`;}).join('')}</div>`:'<div class="empty"><h2>Crie uma trilha primeiro</h2><p>O modelo do planner é vinculado a uma trilha.</p><a class="primary" href="#admin/track/new">Criar trilha</a></div>');return;}
 const track=tracks.find(t=>t.id===trackId);if(!track)return notfound();const template=plannerTemplateFor(track),items=structuredClone(template?.items?.length?template.items:defaultPlannerTasks(track));adminShell('planner','Planner · '+track.title,'Organize tarefas, documentos e orientações que aparecerão para os alunos.',`<section class="editor planner-template-editor"><form id="planner-template-form" class="form"><div class="row">${field('Nome interno do modelo','title',template?.title||'Planner · '+track.title,'text',true)}${select('Publicação','status',[['draft','Rascunho'],['published','Publicado']],template?.status||'draft')}</div><div class="planner-admin-actions"><div><h2>Tarefas do planner</h2><p class="help">As tarefas são independentes das aulas. Use fases para agrupá-las no planner do aluno.</p></div><button type="button" class="outline" id="add-planner-task">+ Nova tarefa</button></div><div id="planner-task-builder"></div>${errorBox}<div class="form-actions"><a class="outline" href="#admin/planner">Cancelar</a><button class="primary" type="submit">Salvar modelo do planner</button></div></form></section>`);
 const draw=()=>{document.querySelector('#planner-task-builder').innerHTML=items.length?items.sort((a,b)=>(a.order||0)-(b.order||0)).map((item,index)=>`<article class="planner-task-editor" data-planner-task="${h(item.id)}"><div class="planner-task-heading"><span>${index+1}</span><strong>${h(item.title||'Nova tarefa')}</strong><button type="button" class="attachment-delete" data-remove-task="${h(item.id)}" aria-label="Remover tarefa">×</button></div><div class="planner-task-fields"><label>Nome da tarefa<input data-task-field="title" value="${h(item.title||'')}" maxlength="160" required></label><label>Fase do processo<input data-task-field="phase" value="${h(item.phase||'')}" maxlength="160" required placeholder="Ex.: Preparação documental"></label><label>Responsável sugerido<input data-task-field="responsibleHint" value="${h(item.responsibleHint||'')}" maxlength="120" placeholder="Aluno, tradutor, advogado..."></label><label>Prioridade<select data-task-field="priority"><option value="low" ${item.priority==='low'?'selected':''}>Baixa</option><option value="normal" ${item.priority==='normal'?'selected':''}>Normal</option><option value="high" ${item.priority==='high'?'selected':''}>Alta</option></select></label><label>Custo estimado<div class="money-field"><select data-task-field="currency"><option value="EUR" ${item.currency==='EUR'?'selected':''}>EUR</option><option value="BRL" ${item.currency==='BRL'?'selected':''}>BRL</option></select><input data-task-field="estimatedCost" type="number" min="0" max="9999999" step="0.01" value="${h(item.estimatedCost??'')}"></div></label><label>Prazo estimado em dias<input data-task-field="dueDays" type="number" min="0" max="3650" value="${h(item.dueDays??'')}" placeholder="Ex.: 30"></label><label class="planner-task-wide">Orientações para o aluno<textarea data-task-field="description" maxlength="2000" placeholder="Explique o objetivo e os próximos passos.">${h(item.description||'')}</textarea></label><label class="planner-task-wide">Documentos previstos<textarea data-task-field="requiredDocuments" maxlength="2000" placeholder="Liste certidões, formulários e comprovantes.">${h(item.requiredDocuments||'')}</textarea></label><label class="planner-required-toggle"><input data-task-field="attachmentRequired" type="checkbox" ${item.attachmentRequired?'checked':''}> Exigir pelo menos um anexo nesta tarefa</label><label>Ordem<input data-task-field="order" type="number" min="0" max="10000" value="${Number(item.order)||index}"></label></div></article>`).join(''):'<div class="empty"><h3>Nenhuma tarefa configurada</h3><p>Adicione a primeira tarefa do processo.</p></div>';document.querySelectorAll('[data-remove-task]').forEach(button=>button.onclick=()=>{const i=items.findIndex(x=>x.id===button.dataset.removeTask);if(i>=0)items.splice(i,1);draw();});};
 const collect=()=>{document.querySelectorAll('[data-planner-task]').forEach(card=>{const item=items.find(x=>x.id===card.dataset.plannerTask);card.querySelectorAll('[data-task-field]').forEach(input=>{item[input.dataset.taskField]=input.type==='checkbox'?input.checked:input.value;});});};draw();document.querySelector('#add-planner-task').onclick=()=>{collect();items.push({id:crypto.randomUUID(),title:'Nova tarefa',phase:'Nova fase',description:'',responsibleHint:'',priority:'normal',estimatedCost:'',currency:'EUR',dueDays:'',requiredDocuments:'',attachmentRequired:false,order:items.length});draw();};attachForm('planner-template-form',async body=>{collect();if(!items.length)throw Error('Adicione pelo menos uma tarefa.');const payload={kind:'planner',trackId:track.id,title:body.title,description:'',status:body.status,order:track.order||0,items:items.map((item,index)=>({...item,order:Number(item.order)||index,estimatedCost:item.estimatedCost===''?'':Number(item.estimatedCost),dueDays:item.dueDays===''?'':Number(item.dueDays)}))};if(template){payload.revision=template.revision;await api('/admin/records/'+template.id,'PUT',payload);}else await api('/admin/records','POST',payload);await loadCatalog();toast('Modelo do planner salvo.');goto('admin/planner');});}

async function usersPage(){const {users,invites}=await api('/admin/users');adminShell('users','Alunos e acessos','Convide pessoas e controle suas permissões.',`<section class="editor"><h2>Gerar convite de acesso</h2><form id="invite-form" class="form"><div class="row">${field('E-mail','email','','email',true)}${select('Perfil','role',[['student','Aluno'],['admin','Administrador']],'student')}</div><fieldset id="invite-access" class="access-fields"><label class="planner-required-toggle"><input type="checkbox" name="grant" checked> Liberar acesso ao curso na ativação</label><div class="row"><label>Curso válido até<input type="date" name="courseExpires" value="${inputDate(Math.floor(Date.now()/1000)+365*86400)}" min="${inputDate(Math.floor(Date.now()/1000)+2*86400)}"></label></div><label class="planner-required-toggle"><input type="checkbox" name="planner"> Incluir o adicional Meu Planner</label><label class="planner-required-toggle"><input type="checkbox" name="fornitore"> Incluir o adicional Fornitore</label></fieldset><small>Administradores podem gerenciar todos os conteúdos e usuários. O link é pessoal, vale por 24 horas e não é enviado automaticamente.</small>${errorBox}<div><button class="primary" type="submit">Gerar convite</button></div></form><div id="invite-result"></div></section><div class="section-title"><h2>Contas cadastradas</h2></div><div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Acesso</th><th>Estado</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${h(u.name)}<small>${h(u.email)}</small></td><td>${u.role==='admin'?'Administrador':'Aluno'}</td><td>${accessCell(u)}</td><td>${badge(u.status)}</td><td><button class="outline" data-user="${h(u.id)}">Gerenciar</button></td></tr>`).join('')}</tbody></table></div><div class="section-title"><h2>Convites e recuperações recentes</h2></div><div class="table-wrap"><table><thead><tr><th>E-mail</th><th>Tipo</th><th>Validade</th><th>Estado</th></tr></thead><tbody>${invites.map(i=>`<tr><td>${h(i.email)}</td><td>${i.kind==='reset'?'Recuperação':'Convite'}</td><td>${h(date(i.expires*1000))}</td><td>${i.used?'Utilizado ou revogado':'Pendente'}</td></tr>`).join('')}</tbody></table></div>`);
 const showInvite=(r)=>{const link=location.origin+'/app#ativar?token='+r.token;document.querySelector('#invite-result').innerHTML=`<div class="invite-result"><strong>Link gerado para ${h(r.email)}</strong><p class="help">Copie e entregue somente à pessoa destinatária. Válido até ${h(date(r.expires*1000))}.</p><textarea readonly aria-label="Link pessoal de acesso">${h(link)}</textarea><button class="outline" id="copy-link">Copiar link</button></div>`;document.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Link copiado.');}catch{document.querySelector('#invite-result textarea').select();toast('Selecione e copie o link.');}};};const inviteForm=document.querySelector('#invite-form');inviteForm.elements.role.onchange=()=>document.querySelector('#invite-access').hidden=inviteForm.elements.role.value!=='student';attachForm('invite-form',async b=>showInvite(await api('/admin/invites','POST',{email:b.email,role:b.role,kind:'invite',...(b.role==='student'&&b.grant?{access:{courseExpires:b.courseExpires,planner:!!b.planner,fornitore:!!b.fornitore}}:{})})));
 document.querySelectorAll('[data-user]').forEach(btn=>btn.onclick=()=>{const u=users.find(u=>u.id===btn.dataset.user);const dialog=document.querySelector('#detail');document.querySelector('#dialog-content').innerHTML=`<h2>${h(u.name)}</h2><p class="muted">${h(u.email)}</p><form class="form" id="user-form">${select('Perfil','role',[['student','Aluno'],['admin','Administrador']],u.role)}${select('Estado','status',[['active','Ativo'],['suspended','Suspenso']],u.status)}${errorBox}<button type="submit" class="primary" ${u.id==='owner'||u.id===user.id?'disabled':''}>Salvar permissões</button><button type="button" class="outline" id="reset-link">Gerar link para nova senha</button><small>Suspender a conta encerra as sessões e bloqueia o acesso.</small></form>${u.role==='student'?accessForm(u):''}`;dialog.showModal();if(u.role==='student')bindAccessForm(u,dialog);attachForm('user-form',async b=>{await api('/admin/users/'+u.id,'PUT',b);dialog.close();await usersPage();toast('Acesso atualizado.');});document.querySelector('#reset-link').onclick=async e=>{e.target.disabled=true;try{const r=await api('/admin/invites','POST',{email:u.email,kind:'reset'});dialog.close();showInvite(r);}catch(err){document.querySelector('#user-form .form-error').textContent=err.message;e.target.disabled=false;}};});}
function accessCell(u){if(u.role==='admin')return 'Completo';const a=u.access;if(!a?.course.active)return a?.course.expired?`<em>Expirou em ${h(dayDate(a.course.expired))}</em>`:'<em>Sem acesso</em>';const extras=['planner','fornitore'].filter(p=>a[p].active).map(p=>productName[p]);return `Curso até ${h(dayDate(a.course.expires))}<small>${extras.length?h(extras.join(' · ')):'Sem adicionais'}</small>`;}
function accessForm(u){const a=u.access,expires=a.course.active?a.course.expires:Math.floor(Date.now()/1000)+365*86400;return `<form class="form access-form" id="access-form"><h3>Acesso à plataforma</h3><label>Curso válido até<input type="date" name="courseExpires" value="${inputDate(expires)}" min="${inputDate(Math.floor(Date.now()/1000)+86400)}" required></label><label class="planner-required-toggle"><input type="checkbox" name="planner" ${a.planner.active?'checked':''}> Adicional Meu Planner</label><label class="planner-required-toggle"><input type="checkbox" name="fornitore" ${a.fornitore.active?'checked':''}> Adicional Fornitore</label>${errorBox}<button type="submit" class="primary">Salvar acesso</button>${a.course.active?'<button type="button" class="outline" id="revoke-access">Remover acesso</button>':''}<small>Os adicionais vencem junto com o curso. As alterações ficam no registro de ações.</small></form><div class="access-history" id="access-history"><p class="help">Carregando histórico…</p></div>`;}
function bindAccessForm(u,dialog){
 const sourceName={admin:'Administração',invite:'Convite',stripe:'Compra'};
 const done=async message=>{dialog.close();await usersPage();toast(message);};
 attachForm('access-form',async b=>{await api('/admin/access/'+u.id,'PUT',{courseExpires:b.courseExpires,planner:!!b.planner,fornitore:!!b.fornitore});await done('Acesso atualizado.');});
 document.querySelector('#revoke-access')?.addEventListener('click',async e=>{if(!confirm('Remover o acesso de '+u.name+' ao curso e aos adicionais?'))return;e.target.disabled=true;try{await api('/admin/access/'+u.id,'PUT',{courseExpires:''});await done('Acesso removido.');}catch(err){document.querySelector('#access-form .form-error').textContent=err.message;e.target.disabled=false;}});
 api('/admin/entitlements?user='+encodeURIComponent(u.id)).then(({entitlements})=>{const box=document.querySelector('#access-history');if(!box)return;box.innerHTML=entitlements.length?`<h3>Histórico</h3><ul>${entitlements.map(e=>`<li><strong>${h(productName[e.product]||e.product)}</strong> até ${h(dayDate(e.expires))} · ${e.status==='active'?'vigente':'substituído'}<small>${h(sourceName[e.source]||e.source)}${e.actorName?' · '+h(e.actorName):''} · ${h(date(e.created*1000))}</small></li>`).join('')}</ul>`:'<p class="help">Nenhum acesso concedido ainda.</p>';}).catch(()=>{const box=document.querySelector('#access-history');if(box)box.innerHTML='<p class="help">Não foi possível carregar o histórico.</p>';});
}
const orderStatus={pending:'Aguardando pagamento',paid:'Pago',failed:'Não aprovado',expired:'Expirado',refunded:'Reembolsado'};
const orderKind={new:'Nova compra',renewal:'Renovação',addon:'Adicional'};
async function salesAdmin(){
 const {settings:s,stripe,orders}=await api('/admin/sales'),paid=orders.filter(o=>o.status==='paid'),money=c=>brl(c).replace(/\s/g,' '),plain=c=>(c/100).toFixed(2).replace('.',',');
 adminShell('sales','Vendas','Preços, desconto de renovação e pedidos pagos pelo Stripe.',`<div class="metrics"><div class="metric"><strong>${h(money(paid.reduce((a,o)=>a+o.amount,0)))}</strong><span>Recebido (últimos 200 pedidos)</span></div><div class="metric"><strong>${paid.length}</strong><span>Pedidos pagos</span></div><div class="metric"><strong>${orders.filter(o=>o.status==='pending').length}</strong><span>Aguardando pagamento</span></div></div>
 ${stripe.payments&&stripe.webhook?'':`<div class="editor stripe-warning"><h2>Stripe ainda não configurado</h2><p class="help">${stripe.payments?'':'Defina STRIPE_SECRET_KEY no ambiente do servidor para abrir as vendas. '}${stripe.webhook?'':'Defina STRIPE_WEBHOOK_SECRET e cadastre o endereço /api/stripe/webhook no painel do Stripe para confirmar Pix, boleto e reembolsos automaticamente.'}</p></div>`}
 <section class="editor"><h2>Preços e renovação</h2><form class="form" id="sales-form"><div class="row">${field('Curso (1 ano), em R$','coursePrice',plain(s.coursePrice),'text',true)}${field('Adicional Meu Planner, em R$','plannerPrice',plain(s.plannerPrice),'text',true)}</div><div class="row">${field('Adicional Fornitore, em R$','fornitorePrice',plain(s.fornitorePrice),'text',true)}${field('Desconto de renovação (%)','renewalDiscount',s.renewalDiscount,'number',true)}</div><div class="row">${field('Desconto válido até quantos dias após o vencimento (0 = sempre)','renewalWindowDays',s.renewalWindowDays,'number',true)}</div><small>A renovação fica disponível nos 60 dias anteriores ao vencimento e depois dele. O desconto vale só para o curso; os adicionais são cobrados pelo preço cheio. Novos preços valem para os próximos pedidos.</small>${errorBox}<div><button class="primary" type="submit">Salvar preços</button></div></form></section>
 <div class="section-title"><h2>Pedidos</h2></div>${orders.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Comprador</th><th>Itens</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td>${h(date(o.created*1000))}<small>${h(orderKind[o.kind]||o.kind)}</small></td><td>${h(o.name)}<small>${h(o.email)}</small></td><td>${h(o.products.map(p=>productName[p]||p).join(' + '))}</td><td>${h(money(o.amount))}${o.discount?`<small>desconto ${h(money(o.discount))}</small>`:''}</td><td>${h(orderStatus[o.status]||o.status)}${o.status==='paid'&&!o.activated?'<small>Senha ainda não criada</small>':''}</td><td>${o.status==='paid'&&!o.activated?`<button class="outline" data-activation="${h(o.id)}">Link de acesso</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Nenhum pedido ainda</h2><p>As compras feitas na página de vendas aparecerão aqui.</p></div>'}<div id="activation-result"></div>`);
 attachForm('sales-form',async b=>{await api('/admin/sales/settings','PUT',{...b,renewalDiscount:Number(b.renewalDiscount),renewalWindowDays:Number(b.renewalWindowDays)});await salesAdmin();toast('Preços atualizados.');});
 document.querySelectorAll('[data-activation]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const r=await api(`/admin/orders/${btn.dataset.activation}/activation`,'POST',{});document.querySelector('#activation-result').innerHTML=`<div class="invite-result"><strong>Link para ${h(r.email)} criar a senha</strong><p class="help">Envie somente a essa pessoa. Válido por 7 dias; gerar outro invalida este.</p><textarea readonly aria-label="Link de acesso">${h(r.link)}</textarea></div>`;document.querySelector('#activation-result').scrollIntoView({behavior:'smooth'});}catch(e){toast(e.message);btn.disabled=false;}});
}
function questionsAdmin(id){const questions=adminRecords.filter(r=>r.kind==='question');if(id){const q=questions.find(q=>q.id===id);if(!q)return notfound();adminShell('questions','Responder dúvida',q.studentName,`<div class="question">${h(q.text)}</div><section class="editor"><form id="answer-form" class="form">${area('Resposta','answer',q.answer)}${errorBox}<button class="primary" type="submit">Salvar resposta</button></form></section>`);attachForm('answer-form',async b=>{await api('/admin/records/'+q.id,'PUT',{...b,revision:q.revision});goto('admin/questions');});return;}adminShell('questions','Dúvidas dos alunos','Responda às perguntas de cada aluno.',`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Dúvida</th><th>Estado</th><th></th></tr></thead><tbody>${questions.map(q=>`<tr><td>${h(q.studentName)}</td><td>${h(q.text.slice(0,140))}<small>${h(adminRecords.find(l=>l.id===q.lessonId)?.title||'')}</small></td><td>${badge(q.status)}</td><td><a class="outline" href="#admin/questions/${h(q.id)}">Responder</a></td></tr>`).join('')}</tbody></table></div>`);}

const providerMoney=p=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:p.currency||'EUR'}).format(p.price||0);
function providerCard(p){return `<article class="provider-card">${p.featured?'<span class="provider-featured">DESTAQUE</span>':''}<div class="provider-photo">${p.photo?`<img src="${h(p.photo)}" alt="${h(p.title)}">`:'<span>'+h(p.title.charAt(0))+'</span>'}</div><div class="provider-card-copy"><small>${h(p.brand||'PROFISSIONAL INDEPENDENTE')}</small><h2>${h(p.title)}</h2><span class="provider-specialty">${h(p.specialty)}</span><p>${h(p.summary||p.description)}</p><div class="provider-rating"><span aria-label="${h(p.rating)} de 5 estrelas">${'★'.repeat(Math.round(p.rating||0))}${'☆'.repeat(5-Math.round(p.rating||0))}</span><small>${p.rating?Number(p.rating).toFixed(1):'Novo'} · ${p.reviewCount||0} avaliações</small></div><div class="provider-card-foot"><strong>A partir de ${h(providerMoney(p))}</strong><a class="primary" href="#fornitore/${h(p.id)}">Saiba mais →</a></div></div></article>`;}
function fornitore(id){const providers=byKind('provider');if(id){const p=providers.find(x=>x.id===id);if(!p)return notfound();main.innerHTML=`<div class="provider-detail"><a class="back" href="#fornitore">← Todos os prestadores</a><section class="provider-profile"><div class="provider-profile-photo">${p.photo?`<img src="${h(p.photo)}" alt="${h(p.title)}">`:'<span>'+h(p.title.charAt(0))+'</span>'}</div><div><span class="eyebrow">${h(p.specialty)}</span><h1>${h(p.title)}</h1><p class="provider-lead">${h(p.summary||p.description)}</p><div class="provider-meta"><span>★ ${p.rating?Number(p.rating).toFixed(1):'Novo'} (${p.reviewCount||0} avaliações)</span>${p.city?`<span>⌖ ${h(p.city)}</span>`:''}${p.languages?`<span>◉ ${h(p.languages)}</span>`:''}</div></div><aside><small>Reunião online</small><strong>${h(providerMoney(p))}</strong><span>${p.duration} minutos</span><a class="primary" href="#fornitore/${h(p.id)}?agendar=1">Solicitar horário</a></aside></section><div class="provider-detail-grid"><article><h2>Sobre o prestador</h2><p class="plaincopy">${h(p.bio||p.description)}</p><h2>Serviços oferecidos</h2><p class="plaincopy">${h(p.services)}</p>${p.credentials?`<h2>Formação e credenciais</h2><p class="plaincopy">${h(p.credentials)}</p>`:''}</article><aside class="provider-booking"><h2>Solicite uma reunião</h2><p>A solicitação será enviada ao prestador. Após a confirmação, ela aparecerá na sua agenda.</p><form id="booking-form" class="form"><label>Data e horário<input name="start" type="datetime-local" required></label>${area('Mensagem para o prestador','message','')}<div class="booking-price"><span>Valor da reunião</span><strong>${h(providerMoney(p))}</strong></div>${errorBox}<button class="primary" type="submit">Enviar solicitação</button><small>A cobrança será processada pela plataforma após a confirmação da disponibilidade.</small></form></aside></div></div>`;attachForm('booking-form',async b=>{const result=await api('/bookings','POST',{providerId:p.id,start:new Date(b.start).toISOString(),message:b.message});document.querySelector('.provider-booking').innerHTML='<div class="booking-success"><span>✓</span><h2>Solicitação enviada</h2><p>O prestador será consultado. Você acompanhará a confirmação na sua agenda.</p><a class="outline" href="#agenda">Ver minha agenda</a></div>';});if(location.hash.includes('agendar=1'))document.querySelector('.provider-booking').scrollIntoView({behavior:'smooth'});return;}main.innerHTML=`<div class="providers-page"><section class="providers-hero"><div><span class="eyebrow">REDE DE ESPECIALISTAS</span><h1>Fornitore</h1><p>Encontre profissionais para apoiar cada etapa da sua jornada entre Brasil e Itália.</p></div><span>Italia, più vicina.</span></section><div class="provider-toolbar"><div><h2>Prestadores verificados</h2><p>${providers.length} profissionais disponíveis na plataforma</p></div><input id="provider-search" placeholder="Buscar por nome ou especialidade" aria-label="Buscar prestadores"></div><div class="provider-grid" id="provider-grid">${providers.map(providerCard).join('')}</div>${!providers.length?'<div class="empty"><h2>Novos especialistas em breve</h2><p>A rede de prestadores está sendo preparada pela administração.</p></div>':''}</div>`;document.querySelector('#provider-search').oninput=e=>{const q=e.target.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelector('#provider-grid').innerHTML=providers.filter(p=>(p.title+' '+p.specialty+' '+p.services).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)).map(providerCard).join('');};}
async function bookingsAdmin(){const {bookings}=await api('/admin/bookings');adminShell('bookings','Reuniões e cobranças','Acompanhe solicitações, confirmações e pagamentos das reuniões.',bookings.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Aluno</th><th>Prestador</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${bookings.map(b=>`<tr><td>${h(date(b.start))}</td><td>${h(b.studentName)}<small>${h(b.studentEmail)}</small></td><td>${h(b.provider)}<small>${h(b.providerEmail)}</small></td><td>${h(new Intl.NumberFormat('pt-BR',{style:'currency',currency:b.currency}).format(b.price))}<small>${h(b.payment_status)}</small></td><td>${h(b.status)}</td><td><button class="outline" data-booking="${h(b.id)}">Gerenciar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Nenhuma reunião solicitada</h2><p>As solicitações dos alunos aparecerão aqui.</p></div>');document.querySelectorAll('[data-booking]').forEach(button=>button.onclick=()=>{const b=bookings.find(x=>x.id===button.dataset.booking),dialog=document.querySelector('#detail');document.querySelector('#dialog-content').innerHTML=`<h2>${h(b.provider)}</h2><p>${h(b.studentName)} · ${h(date(b.start))}</p><form id="booking-admin-form" class="form">${select('Situação','status',[['requested','Solicitada'],['confirmed','Confirmada'],['declined','Recusada'],['cancelled','Cancelada']],b.status)}${select('Pagamento','paymentStatus',[['pending','Pendente'],['paid','Pago'],['refunded','Reembolsado'],['waived','Isento']],b.payment_status)}${field('Link da reunião','meetingUrl',b.meeting_url||'','url')}${errorBox}<button class="primary" type="submit">Salvar reunião</button></form>`;dialog.showModal();attachForm('booking-admin-form',async data=>{await api('/admin/bookings/'+b.id,'PUT',data);dialog.close();await bookingsAdmin();toast('Reunião atualizada.');});});}

function support(){main.innerHTML='<div class="container narrow"><h1 class="page-title">Suporte</h1><div class="support-grid"><article><h2>Dúvidas sobre as aulas</h2><p>Abra uma aula e use a aba Dúvidas. A equipe responderá ali, na sua conta.</p></article><article><h2>Acesso e senha</h2><p>Altere a senha em Meu perfil. Se não conseguir entrar, solicite um link de recuperação à administração.</p></article><article><h2>Seu progresso</h2><p>Marque cada aula concluída ao terminar. Anotações, favoritos e progresso ficam salvos na sua conta.</p></article><article><h2>Conteúdo em produção</h2><p>Alguns módulos ainda estão sendo preparados. As videoaulas aparecerão quando forem publicadas pela equipe.</p></article></div></div>';}
// Acesso inativo (curso) ou extra não contratado (Planner/Fornitore).
function accessPage(product){
 const course=access?.course;
 const title=product==='course'?(course?.expired?'Seu acesso expirou':'Seu acesso ainda não está ativo'):productName[product]+' é um adicional';
 const text=product==='course'?(course?.expired?`Seu acesso ao Arrivo In Itália terminou em ${dayDate(course.expired)}. Seu progresso, suas anotações e seu planner continuam guardados e voltam a ficar disponíveis quando você renovar.`:'Assim que a sua compra for confirmada, as trilhas, as aulas e a agenda ficam disponíveis aqui.'):`${product==='planner'?'Organize documentos, prazos e custos de cada etapa da sua jornada.':'Agende reuniões com especialistas que acompanham cada etapa entre o Brasil e a Itália.'} O adicional vale até o fim do seu acesso ao curso, em ${dayDate(course.expires)}.`;
 main.innerHTML=`<div class="container narrow"><div class="empty access-locked"><span class="empty-icon" aria-hidden="true">${product==='course'?'◷':'◇'}</span><h1>${h(title)}</h1><p>${h(text)}</p><div class="buy-options" id="buy-options"><p class="help">Carregando opções…</p></div><a class="outline" href="#${product==='course'?'perfil':'inicio'}">${product==='course'?'Ver meu perfil':'Voltar ao início'}</a></div></div>`;
 buyOptions(document.querySelector('#buy-options'),product);
}
// Compra dentro da plataforma: renovação do curso (com desconto, quando houver) e adicionais.
const brl=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
async function buyOptions(el,focus){
 let data;try{data=await api('/offer');}catch{el.innerHTML='<p class="help">Não foi possível carregar as opções de compra.</p>';return;}
 const {offer,payments}=data;if(!el.isConnected)return;
 if(!payments){el.innerHTML='<p class="help">As compras pela plataforma abrem em breve. Até lá, fale com a equipe do Arrivo In Itália.</p>';return;}
 let html='';
 if(offer.available.includes('course')){
  const renewExtras=['planner','fornitore'].filter(p=>offer.available.includes(p));
  html+=`<form class="form buy-form" id="renew-form"><p class="buy-headline">${offer.kind==='renewal'?'Renove por mais 1 ano':'Ative seu acesso por 1 ano'}: <strong>${brl(offer.total.course)}</strong>${offer.discountPercent?` <s>${brl(offer.prices.course)}</s> <span class="discount">${offer.discountPercent}% de desconto de renovação</span>`:''}</p>${offer.courseActive?`<small>O novo período começa em ${h(dayDate(offer.courseExpires))}, quando termina o atual. Os adicionais marcados valem para o novo período.</small>`:''}${renewExtras.map(p=>`<label class="planner-required-toggle"><input type="checkbox" name="${p}" ${p===focus&&!offer.courseActive?'checked':''}> Incluir ${h(productName[p])} (+ ${brl(offer.total[p])})</label>`).join('')}${errorBox}<button class="primary" type="submit">Ir para o pagamento</button><small>Cartão, Pix ou boleto, com pagamento seguro pelo Stripe.</small></form>`;
 }
 // Adicionais para o período atual (exigem o curso ativo).
 const extras=offer.courseActive?['planner','fornitore'].filter(p=>!offer.activeExtras.includes(p)):[];
 if(extras.length)html+=`<form class="form buy-form" id="addon-form"><p class="buy-headline">Adicionais para o seu acesso atual</p>${extras.map(p=>`<label class="planner-required-toggle"><input type="checkbox" name="${p}" ${p===focus||extras.length===1?'checked':''}> ${h(productName[p])} — ${brl(offer.total[p])}</label>`).join('')}<small>Válido até o fim do seu acesso ao curso, em ${h(dayDate(offer.courseExpires))}.</small>${errorBox}<button class="primary" type="submit">Adicionar e ir para o pagamento</button></form>`;
 if(!html&&offer.renewalOpens)html=`<p class="help">A renovação com desconto fica disponível a partir de ${h(dayDate(offer.renewalOpens))}.</p>`;
 el.innerHTML=html;
 if(document.querySelector('#renew-form'))attachForm('renew-form',b=>checkoutAccount(['course',...['planner','fornitore'].filter(p=>b[p])]));
 if(extras.length)attachForm('addon-form',b=>checkoutAccount(extras.filter(p=>b[p])));
}
async function checkoutAccount(items){if(!items.length)throw new Error('Escolha pelo menos um item.');const {url}=await api('/checkout/account','POST',{products:items});location.href=url;}
function accessSummary(){if(user.role==='admin')return '';const c=access?.course;return `<section class="editor access-summary"><h2>Seu acesso</h2><ul>${['course','planner','fornitore'].map(p=>{const a=access?.[p];return `<li><span>${h(productName[p])}</span>${a?.active?`<strong>Ativo até ${h(dayDate(a.expires))}</strong>`:`<em>${p==='course'?(c?.expired?'Expirou em '+h(dayDate(c.expired)):'Não ativo'):'Não incluído'}</em>`}</li>`;}).join('')}</ul><small>Os adicionais vencem junto com o curso.</small><div class="buy-options" id="buy-options"></div></section>`;}
function notfound(){main.innerHTML='<div class="container"><div class="empty"><h1>Conteúdo não encontrado</h1><p>Este conteúdo pode não estar publicado.</p><a class="primary" href="#inicio">Voltar ao início</a></div></div>';}
async function render(){const version=++routeVersion;frame();const parts=location.hash.slice(1).split('?')[0].split('/'),route=parts[0]||'inicio';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('selected',a.dataset.nav===route);});document.querySelectorAll('[data-admin-section]').forEach(a=>{const active=route==='admin'&&a.dataset.adminSection===(parts[1]||'');a.classList.toggle('selected',active);if(active)a.setAttribute('aria-current','page');});if(!user||route==='ativar')return authPage();if(!can('course')&&!['perfil','suporte'].includes(route))return accessPage('course');if(['planner','fornitore'].includes(route)&&!can(route))return accessPage(route);try{if(route==='admin'){main.innerHTML='<div class="loading">Carregando administração…</div>';await admin(parts[1]||'',parts[2]);}else if(route==='inicio'||route==='entrar')home();else if(route==='trilha')trail(parts[1]);else if(route==='modulo')modulePage(parts[1]);else if(route==='aula'){let id=parts[1];if(parts[2]){const l=byKind('lesson').filter(l=>l.moduleId===id)[Number(parts[2])];if(!l)return modulePage(id);id=l.id;}await lesson(id);}else if(route==='preview'){if(user.role!=='admin')return notfound();adminRecords=(await api('/admin/records')).records;await lesson(parts[1],true);}else if(route==='agenda')agenda();else if(route==='fornitore')fornitore(parts[1]);else if(route==='planner')await planner();else if(route==='perfil')profile();else if(['historico','favoritos'].includes(route))collection(route);else if(route==='suporte')support();else notfound();}catch(e){if(e.status===401){user=null;access=null;frame();authPage();}else if(e.code?.startsWith('access_')){try{access=(await api('/auth/me')).access;}catch{}frame();accessPage(e.code.slice(7));}else main.innerHTML=`<div class="empty"><h1>Não foi possível carregar</h1><p>${h(e.message)}</p><button class="primary" id="retry">Tentar novamente</button></div>`;document.querySelector('#retry')?.addEventListener('click',render);}if(version===routeVersion)window.scrollTo(0,0);}
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView();};document.querySelector('#detail .close').onclick=()=>document.querySelector('#detail').close();
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});
async function start(){main.innerHTML='<div class="loading">Preparando sua área…</div>';try{try{({user,access}=await api('/auth/me'));}catch(e){if(e.status!==401)throw e;}if(user&&can('course'))await loadCatalog();await render();}catch(e){main.innerHTML=`<div class="empty"><h1>Não foi possível conectar</h1><p>${h(e.message)}</p><button class="primary" id="retry">Tentar novamente</button></div>`;document.querySelector('#retry').onclick=start;}}start();
